// logoAsset.ts
//
// Embeds the real SBP logo (apps/directory-api/public/images/sbp-logo.png,
// 204x213 PNG, 48480 bytes) as a base64 string, decoded at request time by
// routes/logo.ts's GET /logo.png handler.
//
// Why not just reuse the existing public/images/sbp-logo.png the way
// og:image already does (branding.ts): that path works today only because
// Cloudflare's native [assets] binding (wrangler.toml) serves anything
// under ./public directly, before the Worker script runs at all — see
// that file's own doc comment ("this needs no route/handler of its own").
// That mechanism is Workers-production-only: this app's local dev script
// (`tsx watch src/index.ts`, package.json) is a plain Node process with no
// knowledge of wrangler.toml's [assets] directive, so a second file placed
// at public/logo.png would 200 in production but 404 in local dev — unable
// to satisfy this change's own "spin up Worker locally, confirm /logo.png
// returns 200" verification step. A genuine Hono route, by contrast, runs
// identically under local tsx dev and the real Workers runtime (same
// createApp() both environments already share) — but Workers has no
// filesystem access at request time (no `fs.readFileSync`), so the bytes
// have to travel as source, not as a runtime file read. Base64-embedding a
// small (~48KB) binary asset directly in a Workers script is the standard,
// portable technique for exactly this constraint.
export const LOGO_PNG_BASE64 =
  "";

export function getLogoPngBytes(): Uint8Array {
  const binary = atob(LOGO_PNG_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
